// src/utils/colors.js
const stringToHash = (str) => {
  let hash = 0;
  if (!str) return hash;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return hash;
};

export const generateUniqueColor = (throwId) => {
  if (!throwId) return 'hsl(0, 0%, 50%)';
  const hash = stringToHash(throwId);
  const hue = (Math.abs(hash) * 137.508) % 360;
  const saturation = 75;
  const lightness = 50;
  return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
};
